messages.content:
Game edukasi "Prioritas Hidup Run" siap dibangun: pemain berlari sambil memilah barang sesuai target kategori kebutuhan primer, sekunder, atau tersier. Saya memakai tempo Normal (3 nyawa) dan tema Clean Modern sesuai PRD.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "prioritas-hidup-run", title: "Prioritas Hidup Run", seed: "prioritas-hidup-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ekonomi",
    concept: "Tingkat kebutuhan primer, sekunder, dan tersier",
    objectives: [
      "Mengelompokkan barang berdasarkan tingkat prioritas kebutuhan",
      "Membedakan barang yang dibutuhkan dari barang yang tergolong mewah"
    ],
    misconceptions: [
      "Semua yang dibutuhkan untuk hidup dianggap kebutuhan primer"
    ],
    mode: "category",
    categories: [
      { id: "primer",   label: "Primer",   color: "#2F80ED" },
      { id: "sekunder", label: "Sekunder", color: "#27AE60" },
      { id: "tersier",  label: "Tersier",  color: "#9B51E0" }
    ],
    items: [
      { id: "beras",        label: "Beras",             category: "primer",   explain: "Makanan pokok yang wajib dipenuhi lebih dulu." },
      { id: "air-minum",    label: "Air minum",         category: "primer",   explain: "Kebutuhan dasar tubuh; harus dipenuhi paling awal." },
      { id: "rumah",        label: "Rumah sederhana",    category: "primer",   explain: "Tempat tinggal adalah kebutuhan papan yang mendasar." },
      { id: "sepeda",       label: "Sepeda",            category: "sekunder", explain: "Alat transportasi pelengkap; dipenuhi setelah kebutuhan dasar." },
      { id: "buku",         label: "Buku pelajaran",    category: "sekunder", explain: "Penting untuk belajar, tetapi bukan kebutuhan paling dasar." },
      { id: "kulkas",       label: "Kulkas",            category: "sekunder", explain: "Membantu menyimpan makanan, namun tetap pelengkap." },
      { id: "mobil-mewah",  label: "Mobil mewah",       category: "tersier",  explain: "Barang prestise untuk kenyamanan, bukan kebutuhan pokok." },
      { id: "perhiasan",    label: "Perhiasan emas",    category: "tersier",  explain: "Dipenuhi untuk gaya hidup setelah kebutuhan lain terpenuhi." },
      { id: "liburan",      label: "Liburan luar negeri", category: "tersier", explain: "Kebutuhan mewah yang bersifat hiburan, bukan keharusan." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
